import java.util.Scanner;

public class Main {
    public static int findGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int num1 = sc.nextInt();
        int num2 = sc.nextInt();
        int maxDen = sc.nextInt();

        int g = findGCD(num1, num2);
        num1 /= g;
        num2 /= g;

        if (maxDen >= num2) {
            System.out.println(num1 + "/" + num2);
        } else {
            double ratio = (double) num1 / num2;
            double closestDiff = ratio;
            int numerator = 0;
            int denominator = 1;

            for (int i = 1; i <= maxDen; ++i) {
                double candidate = i * ratio;
                double lower = Math.floor(candidate);
                double diffLower = Math.abs(lower / i - ratio);
                double diffUpper = Math.abs((lower + 1) / i - ratio);

                if (closestDiff > diffLower || closestDiff > diffUpper) {
                    if (diffLower > diffUpper) {
                        numerator = (int) (lower + 1);
                    } else {
                        numerator = (int) lower;
                    }
                    denominator = i;
                    closestDiff = Math.min(diffLower, diffUpper);
                }
            }
            System.out.println(numerator + "/" + denominator);
        }
        sc.close();
    }
}
